import React from 'react';
import Plot from 'react-plotly.js';

const data = [
  {
    x: departments.map(dept => dept.department),
    y: departments.map(dept => dept.average_salary),
    type: 'bar',
    marker: { color: 'blue' },
  },
];

const layout = {
  title: 'Average Salary by Department',
  xaxis: {
    title: 'Department',
  },
  yaxis: {
    title: 'Average Salary',
  },
};

const SalaryBarChart = ({ departments }) => {
  return (
    <Plot
      data={data}
      layout={layout}
    />
  );
};

export default SalaryBarChart;
